D = (10,0);
M = (15,0);
C=2*M;
A = D + (scale(1.2)*rotate(aCos((225-144-25)/120))*(M-D));
CC = D + D + D - A - A;
BB = reflect(A,M)*B;
EE = reflect(A,M)*D;
draw(M--A--BB--CC--A--B--C--A);
label("$M$",M,SE);
label("$A$",A,N);
