\multicolumn{1}{r}{2} & 24 & \text{(0 remainder)} \\
\cline{2-3}
\multicolumn{1}{r}{2} & 12 & \text{(0 remainder)} \\
\cline{2-3}
\multicolumn{1}{r}{2} & 6 & \text{(0 remainder)} \\
\cline{2-3}
\multicolumn{1}{r}{2} & 3 & \text{(1 remainder)} \\
\cline{2-3}
\multicolumn{1}{r}{2} & 1 & \text{(1 remainder)} \\
\cline{2-3}
\multicolumn{3}{r}{\text{The process stops here because 1 divided by 2 is 0 with a remainder of 1.}} \\
