label("$P_{n - 1}$", P[3], W);
label("$P_n$", P[4], NE);
label("$a_1$", (A[0] + P[1])/2, E);
label("$a_2$", (A[1] + P[2])/2, E);
label("$a_n$", (A[3] + P[4])/2, E);

dot((21/2 - 0.5,9/2 - 0.5));
dot((21/2,9/2));
dot((21/2 + 0.5,9/2 + 0.5));
