draw((1.32,3.3)--(4,-3.4)--(9.36,3.3),black+linewidth(1));
draw((1.32,3.3)--(4,10)--(9.36,3.3),black+linewidth(1)+dashed);
draw((0,-5)--(4,-5),black+linewidth(1));
